<script setup>
import { Link, useForm } from "@inertiajs/vue3";
import StyledDatePicker from "@/Components/StyledDatePicker.vue";
import EnglishBooksLayout from "@/Layouts/EnglishBooksLayout.vue";
const props = defineProps({ book: { type: Object, required: true } });
const dateOnly = (value) => String(value || "").slice(0, 10);
const form = useForm({ status: props.book.status || "want", started_on: dateOnly(props.book.started_on), finished_on: dateOnly(props.book.finished_on), difficulty: props.book.difficulty || null, interest_rating: props.book.interest_rating || null, recommendation_rating: props.book.recommendation_rating || null, book_overview: props.book.book_overview || "", english_difficulty_note: props.book.english_difficulty_note || "", memo: props.book.memo || "" });
const save = () => { if (form.started_on && form.finished_on && form.finished_on < form.started_on) { form.setError("finished_on", "読了日は読み始めた日以降にしてください。"); return; } form.post(route("admin.englishBooks.update", props.book.id)); };
</script>
<template><EnglishBooksLayout :title="`読書記録を編集 — ${book.title}`"><div class="mx-auto max-w-2xl px-4 py-8 pb-16 sm:px-8 sm:py-14 sm:pb-20"><Link :href="route('admin.englishBooks.index')" class="text-sm font-bold text-[#74665e] hover:text-[#c96b48]">← 本棚に戻る</Link><section class="mt-8 rounded-2xl border border-[#ded7ca] bg-[#fbf9f4] p-5 shadow-[0_8px_30px_rgba(72,55,40,0.06)] sm:p-8"><p class="text-xs font-bold tracking-[0.18em] text-[#c96b48]">わたしの読書記録</p><h1 class="mt-2 break-words font-serif text-3xl font-bold text-[#25323a]">{{ book.title }}</h1><form class="mt-8 grid gap-5 sm:grid-cols-2" @submit.prevent="save"><label><span class="text-sm font-bold text-[#3d4b52]">読書状況</span><select v-model="form.status" class="mt-1.5 block w-full rounded-lg border-[#d6cec1] bg-white text-sm"><option value="want">読みたい</option><option value="reading">読書中</option><option value="finished">読了</option></select></label><label><span class="text-sm font-bold text-[#3d4b52]">難易度（1.0〜5.0）</span><input v-model.number="form.difficulty" type="number" min="1" max="5" step="0.1" inputmode="decimal" class="mt-1.5 block w-full rounded-lg border-[#d6cec1] bg-white text-sm" placeholder="3.5" /></label><label><span class="text-sm font-bold text-[#3d4b52]">面白さ</span><select v-model="form.interest_rating" class="mt-1.5 block w-full rounded-lg border-[#d6cec1] bg-white text-sm"><option :value="null">未設定</option><option v-for="n in 5" :key="n" :value="n">★ {{ n }}</option></select></label><label><span class="text-sm font-bold text-[#3d4b52]">おすすめ度</span><select v-model="form.recommendation_rating" class="mt-1.5 block w-full rounded-lg border-[#d6cec1] bg-white text-sm"><option :value="null">未設定</option><option v-for="n in 5" :key="n" :value="n">★ {{ n }}</option></select></label><label><span class="text-sm font-bold text-[#3d4b52]">読み始めた日</span><StyledDatePicker v-model="form.started_on" :max="form.finished_on" class="mt-1.5" /></label><label><span class="text-sm font-bold text-[#3d4b52]">読了日</span><StyledDatePicker v-model="form.finished_on" :min="form.started_on" class="mt-1.5" /><span v-if="form.errors.finished_on" class="mt-1 text-xs text-rose-600">{{ form.errors.finished_on }}</span></label><label class="sm:col-span-2"><span class="text-sm font-bold text-[#3d4b52]">どんな本？</span><textarea v-model="form.book_overview" rows="3" class="mt-1.5 block w-full rounded-lg border-[#d6cec1] bg-white text-sm" placeholder="習慣を変えるための仕組みを、具体例とともに解説した本。"></textarea></label><label class="sm:col-span-2"><span class="text-sm font-bold text-[#3d4b52]">英語の難しさ</span><textarea v-model="form.english_difficulty_note" rows="3" class="mt-1.5 block w-full rounded-lg border-[#d6cec1] bg-white text-sm" placeholder="文章はかなり平易。専門用語も少なく、洋書初心者にも読みやすい。"></textarea></label><label class="sm:col-span-2"><span class="text-sm font-bold text-[#3d4b52]">感想</span><textarea v-model="form.memo" rows="4" class="mt-1.5 block w-full rounded-lg border-[#d6cec1] bg-white text-sm" placeholder="実践的でかなり面白かった。英語も読みやすいので、自己啓発系の洋書を初めて読む人にもおすすめ。"></textarea></label><div class="sm:col-span-2"><button type="submit" :disabled="form.processing" class="w-full rounded-full bg-[#c96b48] px-7 py-3 text-sm font-bold text-white hover:bg-[#ad5637] disabled:opacity-50 sm:w-auto">読書記録を更新</button></div></form></section></div></EnglishBooksLayout></template>
